func initializeStorage(config *Config) (func(), error) {
	
	
	client, err := ent.Open("postgres", config.DatabaseURL)
	if err != nil {
		return nil, fmt.Errorf("failed opening connection to postgres: %w", err)
	}

	ctx := context.Background()
	if err := client.Schema.Create(
		ctx,
		migrate.WithDropIndex(true),
		migrate.WithDropColumn(true),
	); err != nil {
		_ = client.Close()
		return nil, fmt.Errorf("failed creating schema resources: %w", err)
	}
	log.Println("Database schema migrated successfully")

	storage.SetEntClient(client)
	log.Printf("Ent storage initialized with postgres database")

	return func() {
		if err := client.Close(); err != nil {
			log.Printf("failed to close ent client: %v", err)
		}
	}, nil
	
	
}

